<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Pelican on a bicycle · station blue</title>
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }
    body {
      background: #e6f0fa;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      font-family: 'Segoe UI', Roboto, system-ui, sans-serif;
    }
    .card {
      background: #ffffff;
      border-radius: 2rem;
      box-shadow: 0 20px 40px rgba(0, 30, 60, 0.15);
      padding: 1.5rem 1.5rem 1rem 1.5rem;
      max-width: 1100px;
      width: 100%;
    }
    h1 {
      text-align: center;
      font-size: 2.2rem;
      font-weight: 600;
      letter-spacing: 0.05em;
      color: #1e3b5c;
      margin-top: 0.2rem;
      margin-bottom: 0.8rem;
      text-shadow: 2px 2px 0 #cbdbe9;
    }
    svg {
      display: block;
      width: 100%;
      height: auto;
      border-radius: 1.5rem;
      background: #d9e9f7;
      box-shadow: inset 0 0 0 1px #b3c9dd;
    }
  </style>
</head>
<body>
  <div class="card">
    <h1>🚴 Pelican · station blue</h1>
    <svg viewBox="0 0 1000 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Pelican riding a bicycle on a road with clouds">
      <!-- sky gradient -->
      <defs>
        <linearGradient id="skyGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#b8d8f0"/>
          <stop offset="70%" stop-color="#d4e9fa"/>
          <stop offset="100%" stop-color="#eef6fe"/>
        </linearGradient>
        <linearGradient id="roadGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#5a6b7c"/>
          <stop offset="100%" stop-color="#3e4d5c"/>
        </linearGradient>
        <linearGradient id="wheelGrad" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#2c3e50"/>
          <stop offset="100%" stop-color="#1a252f"/>
        </linearGradient>
        <radialGradient id="hubGrad" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stop-color="#f0f4f8"/>
          <stop offset="100%" stop-color="#b0bec5"/>
        </radialGradient>
        <filter id="softShadow" x="-10%" y="-10%" width="120%" height="120%">
          <feDropShadow dx="0" dy="6" stdDeviation="6" flood-color="#1e3b5c" flood-opacity="0.2"/>
        </filter>
      </defs>

      <!-- sky -->
      <rect width="1000" height="600" fill="url(#skyGrad)"/>

      <!-- clouds -->
      <g fill="#ffffff" opacity="0.85">
        <!-- cloud 1 -->
        <ellipse cx="180" cy="90" rx="70" ry="35"/>
        <ellipse cx="230" cy="70" rx="55" ry="30"/>
        <ellipse cx="130" cy="75" rx="50" ry="28"/>
        <ellipse cx="200" cy="105" rx="60" ry="25"/>
        <!-- cloud 2 -->
        <ellipse cx="720" cy="130" rx="90" ry="40"/>
        <ellipse cx="780" cy="105" rx="65" ry="32"/>
        <ellipse cx="660" cy="110" rx="60" ry="30"/>
